-- ClayDR Enablement Program Manager
INSERT INTO jobs (id, startup_id, title, description, requirements, job_type, location_type, city, country, salary_min, salary_max, currency, application_url, status, created_at, updated_at)
VALUES ('a3577442-4eb2-453f-bd2c-712e054421db', '0455617e-1070-4a2e-a38d-a5ca020222e9', 'ClayDR Enablement Program Manager', 'ABOUT CLAY

Our mission is to help organizations turn any growth idea into reality.

We see growth as a creative practice, not a formula. Finding and reaching your best-fit customers takes unique ideas and constant iteration. As AI makes execution faster and tactics easier to copy, creativity is the only lasting advantage. We''re already helping thousands of customers https://clayrun.notion.site/Wall-of-Love-b243f2b67607438b9fad99341e6b8d47 — including Anthropic, Notion, Google, and Ramp — go to market with unique data, signals, and AI research.

In 2025, we raised a $100M Series C https://www.nytimes.com/2025/08/05/business/dealbook/clay-ai-marketing-fundraise.htmlbacked by world-class investors including Sequoia, CapitalG, and First Round — and crossed $100M in revenue.

In 2026, we announced our second employee tender offer https://www.nytimes.com/2026/01/28/business/dealbook/clay-start-up-tender-offers.html in 9 months at a new $5B valuation. We also launched a community equity round https://www.clay.com/blog/community-equity-offering, for our customers, agency partners, and club members.

Some things to know about us:

 - Our community http://community.clay.com includes 11,000+ customers, 150+ integration partners, 125+ agencies, 50+ Clay clubs https://luma.com/claylive, and 30k members on Slack.

 - Our culture https://nextplayso.substack.com/p/spotlight-clay is unique inside and outside of work. Our team members are also DJs, activists, writers, clowns, marathoners, skydivers, psychedelic therapists, social workers, and more.

 - All employees can work for free with world-class coaches who specialize in creativity, management, and more.

 - Our operating principles — including negative maintenance and non-attached action — guide our work. Read more about them here https://cdn.prod.website-files.com/61477f2c24a826836f969afe/685d83a71452245cc1129791_4d770abfd83e276ec15315a2e06945bd_Clay2025_OperatingPrinciples.pdf.

 - Read about us in the NYT https://www.nytimes.com/2025/08/05/business/dealbook/clay-ai-marketing-fundraise.html, Forbes http://google.com/search?q=forbes+clay&rlz=1C5OZZY_enUS1155US1155&oq=forbes+clay&gs_lcrp=EgZjaHJvbWUyBggAEEUYOTIHCAEQABiABDIHCAIQABiABDIHCAMQABiABDIHCAQQABiABDIHCAUQABiABDIHCAYQABiABDIHCAcQABiABDIHCAgQABiABDIHCAkQABiABNIBBzkzM2owajSoAgOwAgHxBVAe8UAxJx_p&sourceid=chrome&ie=UTF-8, First Round Review https://review.firstround.com/podcast/inside-clays-unconventional-path-to-1-25b/, and more https://www.clay.com/press.
   
   

Hear from our employees directly on our Glassdoor https://www.glassdoor.com/Overview/Working-at-Clay-EI_IE9850794.11,15.htm page!



About the Role

We’re hiring our first ClayDR (SDR) Program Manager to build and scale how Clay enables its ClayDR organization. You’ll own the systems, content, training, and reinforcement programs that help ClayDRs ramp faster, execute with confidence, and consistently generate high-quality pipeline.

Your job is to identify what’s working across our highest-performing ClayDRs, turn it into repeatable programs, and help every ClayDR build the skills, confidence, and habits needed to succeed. As the first dedicated hire in this role, you’ll play a defining role in shaping what great ClayDR enablement looks like at Clay.

You’ll join Clay’s Global Enablement team and partner closely with ClayDR Leadership to build the foundation for a high-performing, scalable ClayDR organization.



What You’ll Do (Job Responsibilities)

 - Design and scale onboarding and ever-boarding programs that accelerate ramp time and set a consistent foundation for success.

 - Build and run workshops and certifications that strengthen ClayDR skills across cold calling, outbound messaging, prospecting, qualification, objection handling, and follow-up.

 - Partner with ClayDR leadership to identify performance gaps across activity, conversion, messaging, and pipeline generation, then build enablement programs that address them.

 - Capture and scale best practices from top-performers through repeatable frameworks and playbooks.

 - Develop and maintain a central hub of resources (playbooks, talk tracks, case studies, templates) to reduce friction and improve knowledge sharing.

 - Translate new product releases and workflows into clear, outbound plays that drive adoption, retention, and expansion.

 - Partner with ClayDR managers to reinforce coaching, inspect adoption, and ensure enablement translates into consistent team behaviors.

 - Measure enablement impact through adoption, performance, engagement, and revenue outcomes.



We’d love to hear from you if:

 - You have 3+ years in an enablement, sales, or SDR, ideally in a high-growth SaaS environment.

 - You have either carried an SDR/outbound number yourself or directly coached SDRs/BDRs responsible for pipeline generation.

 - You deeply understand the outbound motion and what separates strong pipeline from weak pipeline.

 - You’re a strong communicator and facilitator who’s comfortable running workshops, certifications, and executive-level conversations.

 - You’ve built and scaled enablement programs including: onboarding, ever-boarding, certifications, and playbooks that improve performance.

 - You have experience building content and managing enablement systems (e.g., Notion, Gong, or an LMS) to centralize resources and measure adoption.

 - You thrive in fast-paced, high-growth environments and know how to bring structure and clarity without slowing teams down.

 - You’re curious, collaborative, and excited to partner across GTM to help teams drive growth.



What We Provide (Benefits & Perks)

Based out of a central office on 5th Ave in Manhattan near Union Square. We''re big on taking care of our team and always excited to hear different ideas that can help us to do this better.

 - Competitive salary and role trajectory. Roles, responsibilities, and comp grow as we do.

 - Health insurance. Fully funded, high quality health, dental & vision coverage.

 - Visa sponsorship. We get it - it''s an arduous process, but we''re not scared of it.

 - Flexible schedules and paid time off. We ask team members to take at least 2 weeks fully-disconnected per year, with a flexible vacation policy beyond that.

 - Mental health. We''re currently building a plan to help you find coaches, mentors & mental-health services.

 - Annual company retreats

 - Personal comfort. Order whatever equipment you think will help you work more enjoyably.

 - Remote work. Though we prefer people being in-person.

Learn more about Clay, how we think about the world, the vibes and what it’s like to work with us right here https://www.clay.com/meet-clay!', ' - Personal comfort. Order whatever equipment you think will help you work more enjoyably.

 - Remote work. Though we prefer people being in-person.

Learn more about Clay, how we think about the world, the vibes and what it’s like to work with us right here https://www.clay.com/meet-clay!', 'full_time', 'hybrid', 'New York', 'United States', 140000, 200000, 'USD', 'https://jobs.ashbyhq.com/claylabs/13af486b-f105-443f-94f2-29206afb9a77/application', 'active', NOW(), NOW());

