In 2026, we announced our second employee tender offer https://www.nytimes.com/2026/01/28/business/dealbook/clay-start-up-tender-offers.html in 9 months at a new $5B valuation. We also launched a community equity round https://www.clay.com/blog/community-equity-offering, for our customers, agency partners, and club members.

Some things to know about us:

 - Our community http://community.clay.com includes 11,000+ customers, 150+ integration partners, 125+ agencies, 50+ Clay clubs https://luma.com/claylive, and 30k members on Slack.

 - Our culture https://nextplayso.substack.com/p/spotlight-clay is unique inside and outside of work. Our team members are also DJs, activists, writers, clowns, marathoners, skydivers, psychedelic therapists, social workers, and more.

 - All employees can work for free with world-class coaches who specialize in creativity, management, and more.

 - Our operating principles — including negative maintenance and non-attached action — guide our work. Read more about them here https://cdn.prod.website-files.com/61477f2c24a826836f969afe/685d83a71452245cc1129791_4d770abfd83e276ec15315a2e06945bd_Clay2025_OperatingPrinciples.pdf.

 - Read about us in the NYT https://www.nytimes.com/2025/08/05/business/dealbook/clay-ai-marketing-fundraise.html, Forbes http://google.com/search?q=forbes+clay&rlz=1C5OZZY_enUS1155US1155&oq=forbes+clay&gs_lcrp=EgZjaHJvbWUyBggAEEUYOTIHCAEQABiABDIHCAIQABiABDIHCAMQABiABDIHCAQQABiABDIHCAUQABiABDIHCAYQABiABDIHCAcQABiABDIHCAgQABiABDIHCAkQABiABNIBBzkzM2owajSoAgOwAgHxBVAe8UAxJx_p&sourceid=chrome&ie=UTF-8, First Round Review https://review.firstround.com/podcast/inside-clays-unconventional-path-to-1-25b/, and more https://www.clay.com/press.
   
   

Hear from our employees directly on our Glassdoor https://www.glassdoor.com/Overview/Working-at-Clay-EI_IE9850794.11,15.htm page!




DATA @ CLAY

We’re looking for a Data Analyst to help make Clay data-driven from the ground up. You’ll join a team of experienced data scientists and analytics engineers, while partnering closely with Product and Go-to-Market teams to build foundational data models, dashboards, and analyses that teams rely on every day.

This role is ideal for someone earlier in their data career who wants to learn quickly from senior teammates, take on meaningful ownership from day one, and do that work inside one of the fastest-growing AI startups while digging deeply into data to understand why things are happening, not just what is happening.




WHAT YOU’LL DO

 - Build and own analytics data models
   
   - Write clean, maintainable SQL against Snowflake to power core metrics, dashboards, and analytical workflows.

 - Build and iterate on analytics metrics and tables
   
   - Build and iterate on metrics and tables in dbt, and surface them through dashboards in Sigma to help teams understand product usage, performance, and change over time.

 - Explore data deeply to answer open-ended questions
   
   - Use SQL as your primary tool, with Python or R in a notebook environment like Hex when helpful, to investigate trends, anomalies, and product behavior and connect analyses back to real business questions.

 - Help operationalize data
   
   - Support reverse ETL workflows using Census, helping make modeled data actionable in the tools teams use day-to-day.

 - Translate questions into insight
   
   - Partner with cross-functional teams to turn ambiguous questions into clear, useful analytical outputs.


WHAT WE’RE LOOKING FOR

 - Strong SQL fundamentals — comfortable with joins, CTEs, window functions, and clear query structure

 - Experience building analytical data models or metrics tables using dbt or similar analytics-engineering workflows

 - Comfortable working with BI tools like Sigma, Looker, Tableau, Mode, or similar

 - Strong analytical intuition — able to ask the right questions, explore data thoughtfully, and synthesize clear, well-reasoned conclusions

 - Clear communicator who can share insights with technical and non-technical partners

 - Deeply curious about product usage and business performance — motivated to go beyond the what to understand the why, without getting lost in rabbit holes

 - 2+ years of full-time work experience in a related role


NICE TO HAVE

 - Experience with Snowflake or other similar cloud data warehousing tools

 - Comfortable using SQL as the primary analysis tool, with the ability to use Python or R when helpful for deeper or more efficient analysis

 - Familiarity with Hex or other notebook-based analysis tools

 - Familiarity with Census or other reverse ETL tools

 - Prior experience in a product-led or B2B SaaS environment', ' - Familiarity with Hex or other notebook-based analysis tools

 - Familiarity with Census or other reverse ETL tools

 - Prior experience in a product-led or B2B SaaS environment', 'full_time', 'hybrid', 'New York', 'United States', 80000, 100000, 'USD', 'https://jobs.ashbyhq.com/claylabs/31d3597f-400e-4c12-9692-a5fb6f5e0d03/application', 'active', NOW(), NOW());

-- Data Partnerships
INSERT INTO jobs (id, startup_id, title, description, requirements, job_type, location_type, city, country, salary_min, salary_max, currency, application_url, status, created_at, updated_at)
VALUES ('3fbf30a1-5927-4ba2-9c42-de2095feb875', '0455617e-1070-4a2e-a38d-a5ca020222e9', 'Data Partnerships', 'DATA PARTNERSHIPS @ CLAY

Clay''s data ecosystem of 150+ partners is one of our core competitive advantages — and it''s growing fast. We''re looking for a Data Partnerships Manager to be the primary champion for our data partners, ensuring they''re successful, engaged, and getting maximum value from their partnership with Clay.

In this role, you''ll be the main point of contact for a portfolio of data partners, building deep relationships, advocating for their needs internally, and helping them grow their business through Clay. You''ll work cross-functionally with Product, Engineering, Marketing, and Customer Success to make sure our partners have what they need to thrive, while also gathering insights that help us improve our data ecosystem for customers.

If you love building relationships, solving problems, and being the bridge between partners and internal teams, this role is for you.




WHAT YOU''LL DO

Be the voice of our data partners

 - Own relationships with a portfolio of data partners, serving as their primary contact and advocate within Clay.

 - Build trusted relationships through regular communication, quarterly business reviews, and proactive outreach.

 - Deeply understand each partner''s business model, product roadmap, growth goals, and challenges.

Drive partner success and satisfaction

 - Monitor partner health metrics including usage, data quality, customer satisfaction, and commercial performance.

 - Identify opportunities to help partners grow their business through Clay — more visibility, better positioning, co-marketing opportunities, or product improvements.

 - Troubleshoot partner issues quickly, coordinating across internal teams to resolve technical, commercial, or operational challenges.

Advocate internally for partner needs

 - Translate partner feedback into actionable insights for Product, Engineering, and leadership teams.

 - Champion partner priorities in internal discussions, ensuring their perspectives are heard in product roadmaps and strategic decisions.

 - Work with Product and Engineering to improve partner integrations, data presentation, and the overall partner experience.

Enable partner growth through Clay

 - Help partners understand how customers are using their data, what''s working well, and where they can improve.

 - Coordinate co-marketing opportunities, case studies, webinars, and other initiatives that drive value for partners.

 - Share performance insights and best practices to help partners optimize their data quality and coverage.

Ensure operational excellence

 - Track and report on partner performance, satisfaction scores, and engagement metrics.

 - Manage contract renewals and commercial discussions in partnership with leadership.

 - Maintain partner documentation, communication cadences, and relationship management systems.




