-- Enterprise Product Support Specialist
INSERT INTO jobs (id, startup_id, title, description, requirements, job_type, location_type, city, country, salary_min, salary_max, currency, application_url, status, created_at, updated_at)
VALUES ('3e0fd812-7fbe-44fd-848c-eab5b409c4bd', '0455617e-1070-4a2e-a38d-a5ca020222e9', 'Enterprise Product Support Specialist', 'Enterprise Product Support Specialist
Our customers are some of the most innovative and high-impact operators in the world. As an Enterprise Support Specialist, you’ll be the primary technical and strategic partner for Clay’s largest, most complex, and highest-value customers—ensuring their long-term success while influencing how we deliver exceptional enterprise-grade support. You’ll own relationships with enterprise accounts post-onboarding, resolve their most complex technical challenges, design tailored workflows, and partner closely with Product, Engineering, and Customer Success to deliver solutions that drive measurable outcomes. You’ll also help refine our enterprise support playbook and set the standard for operational excellence.





WHAT YOU’LL DO

 - Own enterprise-level technical cases end-to-end, from triage through resolution, ensuring minimal disruption to customer operations.

 - Serve as a trusted advisor for strategic accounts—understanding their business goals and proactively recommending workflows, configurations, and integrations to meet them.

 - Act as the highest-level subject matter expert on Clay’s product, advanced features, APIs, and data integration capabilities.

 - Partner with Customer Success to deliver seamless, proactive support that strengthens long-term relationships and drives product adoption.

 - Collaborate closely with Product and Engineering to escalate critical issues through high-quality bug reports, structured feedback, and advocating for enterprise needs in roadmap discussions.

 - Develop and maintain enterprise-facing resources such as technical runbooks, playbooks, and best-practice guides.

 - Support customers and cross-functional partners during issue escalations and incident events.

 - Identify patterns across accounts to recommend product improvements, process changes, or automation opportunities.

 - Contribute to strategic process design, shaping how Clay supports and scales with enterprise customers.



WHAT YOU’LL BRING

 - Extensive technical expertise—fluent in APIs, complex data integrations, log analysis, and SaaS architecture, with the ability to troubleshoot across enterprise tech stacks like Salesforce.

 - Proven track record in enterprise SaaS support, technical account management, or solutions engineering, ideally in a high-growth startup.

 - Exceptional consultative skills—able to translate business needs into technical solutions.

 - Enterprise relationship management experience—comfortable navigating multi-stakeholder environments and executive conversations.

 - Customer obsession—committed to delivering measurable value and long-term success.

 - Process and systems thinking—adept at identifying inefficiencies and designing scalable solutions.

 - Experience collaborating cross-functionally with Product, Engineering, and Customer Success teams.

 - Comfortable in fast-paced, evolving environments where priorities can shift quickly.', ' - Process and systems thinking—adept at identifying inefficiencies and designing scalable solutions.

 - Experience collaborating cross-functionally with Product, Engineering, and Customer Success teams.

 - Comfortable in fast-paced, evolving environments where priorities can shift quickly.', 'full_time', 'hybrid', 'New York; San Francisco', 'United States', 130000, 160000, 'USD', 'https://jobs.ashbyhq.com/claylabs/4623405b-1062-4019-9979-129a86408d7b/application', 'active', NOW(), NOW());

-- Events Marketing
INSERT INTO jobs (id, startup_id, title, description, requirements, job_type, location_type, city, country, salary_min, salary_max, currency, application_url, status, created_at, updated_at)
VALUES ('c0c775d7-61ea-4ab9-b9d5-4be0c6bf75b0', '0455617e-1070-4a2e-a38d-a5ca020222e9', 'Events Marketing', 'EVENTS MARKETING @ CLAY

We''re looking for a seasoned B2B events professional who can manage the strategy, production, and delivery of our European events program. You''ll be responsible for building experiences that bring together enterprise buyers, partners, and the broader tech community - from intimate executive dinners to larger meetups and summits to third-party conferences that we sponsor.

You''ll own the events roadmap end-to-end, both building the strategy and executing on it. That means managing vendors across multiple countries, coordinating production timelines, and ensuring every event feels polished, purposeful, and unmistakably Clay. You''ll work hand-in-hand with marketing, sales, partnerships, and customer success to make sure every activation ties back to real business impact.




WHAT YOU''LL DO

 - Drive the European events program: Work with the Head of Events in San Francisco to plan, produce, and deliver a portfolio of B2B events across key European tech hubs, including London, Berlin, Amsterdam, and Stockholm. Formats will range from large-scale conferences to intimate dinners to hosted events at industry summits.

 - Connect event strategy to business outcomes: Partner with marketing and sales leadership to define event goals, target audiences, and success metrics. Every event should have clear goals and a measurable impact on pipeline, brand awareness, and customer engagement.

 - Manage events end-to-end and build vendor relationships across Europe: Handle the venue sourcing, vendor negotiations, run-of-show planning, and on-the-day execution. You''ll develop a trusted roster of vendors who can deliver consistently at a high standard.

 - Coordinate cross-functional stakeholders: Lead planning syncs, keep workstreams on track, and ensure that busy internal teams are prepped and aligned without being overwhelmed.

 - Manage budgets with discipline: Own event budgets, track spend meticulously, negotiate favorable terms, and ensure every pound and euro is well spent.

 - Handle multi-market logistics: Navigate the practicalities of producing events across different countries - permits, local regulations, cultural considerations, language needs, and timezone coordination.

 - Develop scalable processes: Build repeatable playbooks, templates, and frameworks so the events programme can grow without quality dropping off.




WHAT YOU''LL BRING

 - 5+ years of experience in B2B event production, with a strong track record of delivering events in European markets.

 - Multi-city, multi-country experience. You''ve produced events across at least two or three European markets and understand key differences between them.

 - Strong production instinct. You care about the flow and vibe of the attendee experience, not just logistics. You notice the details that most people miss.

 - Experienced with tracking ROI. You understand how events connect to pipeline, revenue, and brand goals. You can speak the language of sales and marketing as fluently as you speak production.

 - Excellent vendor and budget management skills. You''ve managed large event budgets and have experience negotiating contracts across multiple markets.

 - A calm, organised presence under pressure. Live events can go sideways sometimes. You stay steady, solve problems fast, and keep the team focused.

 - Strong communication and stakeholder management. You''re comfortable working with senior leadership, guiding executives through rehearsals, and keeping cross-functional teams aligned.

 - Fluent English required. Additional European languages (German, Dutch, Swedish, or others) are great but not essential.




NICE TO HAVE

 - Experience in the GTM-Tech or SaaS sector.

 - Familiarity with event technology platforms (registration, engagement tools, lead capture).

 - A network of trusted vendors and venues across European tech hubs.', 'WHAT YOU''LL BRING

 - 5+ years of experience in B2B event production, with a strong track record of delivering events in European markets.

 - Multi-city, multi-country experience. You''ve produced events across at least two or three European markets and understand key differences between them.

 - Strong production instinct. You care about the flow and vibe of the attendee experience, not just logistics. You notice the details that most people miss.

