NICE TO HAVE

 - Experience in the GTM-Tech or SaaS sector.

 - Familiarity with event technology platforms (registration, engagement tools, lead capture).

 - A network of trusted vendors and venues across European tech hubs.', 'full_time', 'hybrid', 'London', 'United Kingdom', 200000, 300000, 'USD', 'https://jobs.ashbyhq.com/claylabs/d23dfc5b-2d75-412c-bedf-38643517b486/application', 'active', NOW(), NOW());

