-- Founding Marketer, EMEA
INSERT INTO jobs (id, startup_id, title, description, requirements, job_type, location_type, city, country, currency, application_url, status, created_at, updated_at)
VALUES ('301235da-b492-453e-b408-c822f54ec5cd', '0455617e-1070-4a2e-a38d-a5ca020222e9', 'Founding Marketer, EMEA', 'FOUNDING MARKETER, EMEA

Clay is expanding into EMEA, and we''re hiring our first Marketer in the region to establish our brand and drive revenue as we scale. You''ll own foundational positioning and messaging for the market, while working in lockstep with sales to build enablement materials and demand generation that actually moves deals.

This is a hands-on, execution-focused role for someone who wants to build marketing infrastructure from scratch and directly influence revenue. You''ll translate Clay''s product capabilities into narratives that resonate with EMEA enterprise buyers, test and refine messaging in real sales conversations, and help set up a repeatable enterprise motion. If you want to shape how an entire region understands and buys a category-defining product, this is the role.




WHAT YOU’LL DO

Define Clay’s positioning within EMEA

 - Define and evolve Clay’s positioning, messaging, and ICPs for EMEA enterprise buyers

 - Translate Clay’s product capabilities into clear, differentiated value propositions and use cases

 - Identify where EMEA buyer needs, language, and buying dynamics differ from the US and adapt the story accordingly

 - Pressure-test messaging in real sales conversations and refine continuously

Lead sales enablement through product storytelling

 - Partner closely with EMEA Sales and GTM-Engineering (GTM Ops) to support active deals

 - Create and iterate on sales enablement assets (core pitch, narratives, one-pagers, use cases, competitive context)

 - Help sales teams articulate why Clay, why now, and why us vs alternatives

 - Ensure consistency in how Clay is positioned across the full enterprise buying committee

Use field marketing and community events to validate and reinforce the message

 - Support in-person community events, executive dinners, and conferences in EMEA

 - Define event themes, talk tracks, and narratives rooted in product value

 - Decide who should be invited based on ICP fit and active opportunities

 - Capture qualitative feedback from the field to inform positioning and enablement

Close the feedback loop with Product and Marketing

 - Synthesize insights from sales calls, demos, objections, and wins/losses

 - Share EMEA-specific learnings with Product Marketing and Product teams

 - Influence roadmap, packaging, and messaging with real buyer evidence

 - Refine Clay’s story based on what actually moves deals




WHAT YOU’LL BRING

 - Strong product marketing foundation in B2B SaaS. You’ve owned positioning, messaging, and narratives for complex products. Ideally, in sales-led or enterprise contexts.

 - Experience supporting enterprise sales motions. You’ve worked closely with sales on live deals, understand buying committees, and know how to enable sales with the right story at the right moment.

 - Ability to translate product depth into clarity. You can take technical or complex capabilities and turn them into clear, compelling value props that resonate with executive and practitioner buyers.

 - Hands-on mindset with a bias toward execution. You’re comfortable going from strategy to doing - building enablement assets, shaping campaigns, supporting events, and iterating quickly based on feedback.

 - Strong written and verbal communicator. You’re an excellent writer and presenter, able to craft narratives, one-pagers, decks, and talk tracks that sales teams actually use.

 - Commercial and analytical instincts. You think in terms of pipeline, deal progression, and buyer objections - not just awareness or engagement metrics.

 - Comfort operating in ambiguity. You’ve thrived in early or fast-moving environments where the scope isn’t fully defined, and ownership matters more than process.

 - Bonus: modern GTM tooling experience. Familiarity with tools like Clay, Salesforce, outbound platforms, or ABM workflows is a plus - but curiosity and learning speed matter more.', ' - Commercial and analytical instincts. You think in terms of pipeline, deal progression, and buyer objections - not just awareness or engagement metrics.

 - Comfort operating in ambiguity. You’ve thrived in early or fast-moving environments where the scope isn’t fully defined, and ownership matters more than process.

 - Bonus: modern GTM tooling experience. Familiarity with tools like Clay, Salesforce, outbound platforms, or ABM workflows is a plus - but curiosity and learning speed matter more.', 'full_time', 'remote', 'London', 'United Kingdom', 'USD', 'https://jobs.ashbyhq.com/claylabs/9724f8a6-0e59-4488-b3e1-110760d478c3/application', 'active', NOW(), NOW());

-- Founding Sourcer
INSERT INTO jobs (id, startup_id, title, description, requirements, job_type, location_type, city, country, salary_min, salary_max, currency, application_url, status, created_at, updated_at)
VALUES ('092831b0-4785-4fe4-bdee-c31dfb4739cf', '0455617e-1070-4a2e-a38d-a5ca020222e9', 'Founding Sourcer', 'FOUNDING SOURCER



Clay’s recruiting team has nearly doubled in size in the last 6 months, and we’re excited to build out our founding sourcing team. In this role, you’ll partner with incredible hiring managers, recruiters, and coordinators to experiment in how sourcing should work at an AI-forward company, build funnel for our highest volume roles, as well as research and map unique roles and ever-expanding geographies.

We’re so ready to be unlocked by our sourcing team. We have really lovely hiring managers who know what they’re looking for (and are still willing to experiment and iterate), well-documented interview processes, and wonderful recruiters and coordinators who are excited to collaborate and help you inflect our hiring during a really special growth phase for clay.

Clay (our product) has the potential to be one of the strongest sourcing tools on the market - joining this team will give you a chance to build on our own infrastructure, and influence the way many other companies’ recruiting and sourcing teams find recruiting alpha!

Our sourcing team will be at the center of our recruiting team at clay, where all of us will gravitate toward for great ideas, automations, AI tooling, and of course, incredible future claymates.



What you need:

 - 5+ years’ experience sourcing and/or recruiting in high growth tech environments

 - Creativity to help you generate amazing copy and sourcing ideas

 - Tenacity: we’re building this function from scratch! There will undoubtedly be iterations as we figure out what works

 - Tinkering prowess and Adaptability: we’ll use clay as our main sourcing tool, and will try out other tools along the way, so you’ll need to be ready to tinker, change up your workflow, and try new things all the time!
   
   

What you’ll do:

 - Find creative recruiting alpha to engage incredible talent for clay

 - Experiment with tools and automations to help make everyone at clay (hiring managers and recruiters too!) more effective sourcers

 - Write great copy, and experiment with all sorts of drip campaigns and conversation starters

 - Source from within! Generate referrals from all our amazing claymates, and figure out ways to do this at a larger and larger scale

 - Research! Figure out new geos, industries, roles, and how we can engage the talent we need at just the right time

 - Optimize your efforts by checking in on funnel metrics, from first touch to offer accept

 - Partner closely with recruiters to anticipate and work against upcoming headcount', ' - Research! Figure out new geos, industries, roles, and how we can engage the talent we need at just the right time

 - Optimize your efforts by checking in on funnel metrics, from first touch to offer accept

 - Partner closely with recruiters to anticipate and work against upcoming headcount', 'full_time', 'hybrid', 'New York', 'United States', 180000, 220000, 'USD', 'https://jobs.ashbyhq.com/claylabs/be9a2c48-e7ae-4228-8df0-ca4fd5fff388/application', 'active', NOW(), NOW());

-- Front Desk Coordinator
INSERT INTO jobs (id, startup_id, title, description, requirements, job_type, location_type, city, country, salary_min, salary_max, currency, application_url, status, created_at, updated_at)
VALUES ('ef5af146-dd9e-45b8-9765-b1ed2892dec0', '0455617e-1070-4a2e-a38d-a5ca020222e9', 'Front Desk Coordinator', 'FRONT DESK COORDINATOR @ CLAY

Clay is excited to operate as an in-person company across our 3 global offices. Clay believes that creative magic happens when we''re collaborating in-person. We also believe that being in the same physical space is the key to building a lasting culture.

We''re looking for a Front Desk Coordinator at our New York City headquarters who will be the first point of contact for employees, visitors, and partners. This role is about more than checking people in — you''ll set the tone for their entire experience at Clay. You''ll bring warmth, professionalism, and care to every interaction, while also ensuring smooth operations around access, mail, safety, and events. The right candidate will report to our Workplace Experience Lead, with the ability to become a full time employee!



WHAT YOU''LL ACHIEVE

 - Reception Excellence: Provide a warm, professional welcome to all visitors and employees, creating a positive first impression of Clay as the face of our headquarters.

 - Experience Stewardship: Anticipate needs, resolve issues quickly, and make interactions seamless, whether for a candidate interview, executive visitor, or new hire on their first day.

 - Building Coordination & Communication: Submit candidate registration and building tickets, and communicate office maintenance concerns.

 - Access Control & Security: Manage Clay''s entry points, verify identification badges, and process visitor registration through Envoy while ensuring all security protocols are followed.

 - Administrative Accuracy: Maintain detailed daily logs, incident reports, and security documentation while promptly reporting maintenance and safety issues.

 - Event Support: Facilitate seamless visitor experiences during events by managing registration, badge distribution, and NDA completion while coordinating with the Workplace Experience Team.

 - Package & Mail Management: Efficiently log and distribute all incoming mail and packages, maintaining an organized package room and timely delivery system.

 - AI Integration & Innovation: Integrate and push the boundaries on how we work to create a more seamless and forward-thinking visitor experience.


WHAT YOU''LL BRING

 - 2+ years of relevant workplace experience.

 - Strong emotional intelligence (EQ) with the ability to build relationships at all levels: You connect easily with people, create a sense of ease, and leave a positive impression in every interaction

 - Flexibility: adapt and switch between various responsibilities and priorities on any given day.

 - Organized and detail-oriented: Strong attention to detail, able to stay calm under pressure, a quick thinker, create order out of chaos.

 - Polished communication: Clear, professional, and approachable — in person, over the phone, and in writing. Able to represent Clay to executives, candidates, and partners as the first face people see when coming to the office.

 - Discreet: Demonstrated ability to maintain complete confidentiality on all business matters.

 - Cross-functional relationships: Coordinate with multiple teams to provide exemplary service, while being a social steward and bringing people together.', 'WHAT YOU''LL BRING

 - 2+ years of relevant workplace experience.

 - Strong emotional intelligence (EQ) with the ability to build relationships at all levels: You connect easily with people, create a sense of ease, and leave a positive impression in every interaction

 - Flexibility: adapt and switch between various responsibilities and priorities on any given day.

 - Organized and detail-oriented: Strong attention to detail, able to stay calm under pressure, a quick thinker, create order out of chaos.

 - Polished communication: Clear, professional, and approachable — in person, over the phone, and in writing. Able to represent Clay to executives, candidates, and partners as the first face people see when coming to the office.

 - Discreet: Demonstrated ability to maintain complete confidentiality on all business matters.

 - Cross-functional relationships: Coordinate with multiple teams to provide exemplary service, while being a social steward and bringing people together.', 'full_time', 'hybrid', 'New York', 'United States', 85000, 100000, 'USD', 'https://jobs.ashbyhq.com/claylabs/34d69869-d436-4cac-b7df-aa42b32817c2/application', 'active', NOW(), NOW());

