 - Bonus points for experience in analytics engineering, data science and /or programming languages

 - Bonus points for: Salesforce Administrator, Developer, or CPQ Specialist certification, experience as a software / infrastructure engineer



Why This Role Is Different

Clay is GTM infrastructure so this is not a traditional Salesforce admin role.

The discipline you help to pioneer will look more like applied site reliability engineering using Clay. By necessity you will be a builder — someone who takes messy business processes and turns them into clean, reliable systems that GTM teams can actually depend on. That means understanding how the revenue motion works, designing for scale, and treating Salesforce as a product that needs to be maintained and improved over time.', 'full_time', 'hybrid', 'New York', 'United States', 140000, 180000, 'USD', 'https://jobs.ashbyhq.com/claylabs/f90028b7-6c35-4392-824c-105967ccd406/application', 'active', NOW(), NOW());

