 - Act as a partner to the AMER sales team and the AMER sales operations lead, providing hands-on operational support to drive deals forward and advising with decision-making

 - Ensure that the internal GTM Engineering team is prioritizing and roadmapping automations and applications needed locally, building prototypes, and deploying solutions yourself

 - Extend the global business locally: ensure that sales methodologies and procedures are embedded into the business



