ABOUT CLAY UNIVERSITY

Clay University is the core IP of the GTME Ecosystem — the definitive place where thousands of Go-to-Market Engineers (GTMEs) learn what good looks like. It’s where people go from “I’ve heard of GTME” to “I think like a GTME.” Docs, courses, Cohorts, guides, and the entire library of content that teaches the emerging discipline of GTM Engineering all roll up here.

This is a mini-founder role. You’ll think about Clay University the way a founder thinks about their product — with a strong opinion on the persona journey, ruthless prioritization of what to ship, and a refusal to accept that the current pace is the fastest we can go. That means owning:


WHAT YOU’LL DO

 - Own the strategic vision for Clay University. You’ll build the persona journey map (new user → power user → GTM leader) and the content roadmap that serves it, collaborating with the brand and website team to create the single best hub for GTMEngineering the world has ever seen.

 - Ship more, faster, without dropping the bar. The pace of AI development continues to evolve. Our content velocity needs to evolve with it. You’ll work on creating content yourself, hiring content creators to build out more content, and ensure that our content covers everything users would want under the GTME Sun.

 - Lead and grow the University content team. This is player-coach role. Part of your job will be to unblock the existing team, sharpen their work, and take the strategic/planning weight off their plates. Additionally you’ll help build content partnerships or hire content creators to help us continue to keep pace.

 - Build the cross-functional content pipeline. Our Solutions team produces golden content every day for customers. Our internal GTMOps team is constantly pushing the edges of great content. The Forward Deployed GTME team creates crazy tables builds. You’ll create processes and systems to make sure these critical innovations are accessible to the global GTME community.

 - Launch experimental programs. Should we have a visiting professors program? Community-authored guides? Asynchronous peer-review mechanisms? The world is your oyster.

 - Make content a defensible flywheel for GTME Ecosystem brand and inbound. You’ll measure what resonates, double down, and kill what doesn’t. Don’t stay limited to “Clay” content - we’re building something bigger here. We will build the world’s best automation content ecosystem, inclusive of GTM engineering.


WHO YOU ARE

 - A content creator with a founder’s gut. You can write the thing yourself when you need to, but your superpower is seeing the system.

 - A learner first, a teacher second. When a frontier model drops a new release, you’re playing with it that evening.

 - Obsessed with shipping cadence. You know that a great piece of content shipped this week beats a perfect piece shipped next quarter.

 - Comfortable in ambiguity. There’s no established playbook for what the definitive university for an emerging discipline should look like. Don’t rely on old playbooks, build the AI-native one.

 - Proven hunger, not just potential. You’ve already run a content function, a program, or a publication where the pace and the bar were both yours to set.


WHO YOU ARE NOT

 - A content strategist who doesn’t ship. You’ll write the strategy doc and then write the article, record the Loom, and build the course landing page. End to end ownership.

 - A leader who knows how to delegate. This is a player-coach role, not a management role. You’re excited to get your hands dirty and lead a team.

 - An editor who loses the reader. You care about craft, but you care more about the learner’s experience.

 - Someone who thinks GTME University is “just content.” It’s the primary brand surface of the entire GTME Ecosystem. A home for all our programs and our content.

 - A systematizer before a prover. The first instinct should be to ship scrappy experiments.', 'WHO YOU ARE

