VALUES ('5507e857-49c9-454b-b644-fcfff45d2c1f', '0455617e-1070-4a2e-a38d-a5ca020222e9', 'Growth Strategist, Enterprise (Customer Success)', 'ABOUT CLAY

Our mission is to help organizations turn any growth idea into reality.

We see growth as a creative practice, not a formula. Finding and reaching your best-fit customers takes unique ideas and constant iteration. As AI makes execution faster and tactics easier to copy, creativity is the only lasting advantage. We''re already helping thousands of customers https://clayrun.notion.site/Wall-of-Love-b243f2b67607438b9fad99341e6b8d47 — including Anthropic, Notion, Google, and Ramp — go to market with unique data, signals, and AI research.

In 2025, we raised a $100M Series C https://www.nytimes.com/2025/08/05/business/dealbook/clay-ai-marketing-fundraise.htmlbacked by world-class investors including Sequoia, CapitalG, and First Round — and crossed $100M in revenue.

In 2026, we announced our second employee tender offer https://www.nytimes.com/2026/01/28/business/dealbook/clay-start-up-tender-offers.html in 9 months at a new $5B valuation. We also launched a community equity round https://www.clay.com/blog/community-equity-offering, for our customers, agency partners, and club members.

Some things to know about us:

 - Our community http://community.clay.com includes 11,000+ customers, 150+ integration partners, 125+ agencies, 50+ Clay clubs https://luma.com/claylive, and 30k members on Slack.

 - Our culture https://nextplayso.substack.com/p/spotlight-clay is unique inside and outside of work. Our team members are also DJs, activists, writers, clowns, marathoners, skydivers, psychedelic therapists, social workers, and more.

 - All employees can work for free with world-class coaches who specialize in creativity, management, and more.

 - Our operating principles — including negative maintenance and non-attached action — guide our work. Read more about them here https://cdn.prod.website-files.com/61477f2c24a826836f969afe/685d83a71452245cc1129791_4d770abfd83e276ec15315a2e06945bd_Clay2025_OperatingPrinciples.pdf.

 - Read about us in the NYT https://www.nytimes.com/2025/08/05/business/dealbook/clay-ai-marketing-fundraise.html, Forbes http://google.com/search?q=forbes+clay&rlz=1C5OZZY_enUS1155US1155&oq=forbes+clay&gs_lcrp=EgZjaHJvbWUyBggAEEUYOTIHCAEQABiABDIHCAIQABiABDIHCAMQABiABDIHCAQQABiABDIHCAUQABiABDIHCAYQABiABDIHCAcQABiABDIHCAgQABiABDIHCAkQABiABNIBBzkzM2owajSoAgOwAgHxBVAe8UAxJx_p&sourceid=chrome&ie=UTF-8, First Round Review https://review.firstround.com/podcast/inside-clays-unconventional-path-to-1-25b/, and more https://www.clay.com/press.
   
   

Hear from our employees directly on our Glassdoor https://www.glassdoor.com/Overview/Working-at-Clay-EI_IE9850794.11,15.htm page!




ENTERPRISE GROWTH STRATEGIST @ CLAY

As one of Clay’s Enterprise Growth Strategists, you’ll partner with some of the fastest-growing SaaS companies in the world (think Intercom, Verkada, Anthropic) to define, scale, and continuously expand their Clay strategy.

You’ll work directly with senior GTM leaders to:

 - Map their growth priorities

 - Translate those into actionable Clay use cases

 - Expand Clay into new teams and workflows

 - Shape the roadmap of both their GTM engine and Clay itself

You are not just supporting customers, you’re a strategic business partner, trusted advisor, and internal product voice.




WHAT YOU’LL DO

 - Onboard with velocity & vision: Guide customers to their first “aha” moment in Clay, ensuring fast time-to-value while positioning Clay as a long-term strategic lever.

 - Be a growth partner: Act as an extension of our customers’ GTM teams by co-creating new plays, uncovering fresh use cases, and helping them stay ahead of their competitors.

 - Drive ongoing adoption & expansion: Continuously identify opportunities for Clay across sales, revops, marketing, and CX, expanding Clay’s footprint within the org.

 - Shape renewal outcomes: By driving outsized value, ensure every customer sees Clay as indispensable, leading to strong renewals and multi-team expansions.

 - Influence our roadmap: Synthesize patterns from enterprise accounts and collaborate with Product, Engineering, and Design to bring customer-driven innovation to Clay.

 - Build new programs from scratch: Design scalable frameworks, playbooks, and initiatives for future Enterprise customers.




WHAT YOU’LL BRING

This role is for someone who wants to sit at the intersection of customer strategy, product vision, and GTM innovation and help some of the fastest-growing companies in the world find their edge with Clay.

 - Strategic, product-minded thinking: You don’t just solve today’s problem: you see around corners, help customers envision what’s next, and connect their roadmap to ours.

 - Deep GTM fluency: You’ve lived in B2B SaaS and can speak the language of revops, sales, and marketing leaders. Bonus if you’ve held an in-house GTM operator role.

 - Customer obsession with business savvy: You’ve worked directly with customers (not just managed accounts) and you know how to build trust, challenge thinking, and deliver impact.

 - Builder DNA: You thrive in ambiguity, love creating structure where none exists, and get energy from designing processes and teams from 0 → 1.

 - Passion for Clay: You believe in our mission and are excited to evangelize Clay as if it were your own product.', ' - Customer obsession with business savvy: You’ve worked directly with customers (not just managed accounts) and you know how to build trust, challenge thinking, and deliver impact.

 - Builder DNA: You thrive in ambiguity, love creating structure where none exists, and get energy from designing processes and teams from 0 → 1.

 - Passion for Clay: You believe in our mission and are excited to evangelize Clay as if it were your own product.', 'full_time', 'hybrid', 'London', 'United Kingdom', 130000, 180000, 'USD', 'https://jobs.ashbyhq.com/claylabs/9d4828b2-8c23-406d-8225-b916ff9174c0/application', 'active', NOW(), NOW());

-- Growth Strategist, Enterprise (Customer Success)
