-- Head of Solutions Engineering
INSERT INTO jobs (id, startup_id, title, description, requirements, job_type, location_type, city, country, salary_min, salary_max, currency, application_url, status, created_at, updated_at)
VALUES ('cda98236-65c5-42d2-b1f0-671218c4d4f5', '0455617e-1070-4a2e-a38d-a5ca020222e9', 'Head of Solutions Engineering', 'ABOUT CLAY

Our mission is to help organizations turn any growth idea into reality.

We see growth as a creative practice, not a formula. Finding and reaching your best-fit customers takes unique ideas and constant iteration. As AI makes execution faster and tactics easier to copy, creativity is the only lasting advantage. We''re already helping thousands of customers https://clayrun.notion.site/Wall-of-Love-b243f2b67607438b9fad99341e6b8d47 — including Anthropic, Notion, Google, and Ramp — go to market with unique data, signals, and AI research.

In 2025, we raised a $100M Series C https://www.nytimes.com/2025/08/05/business/dealbook/clay-ai-marketing-fundraise.htmlbacked by world-class investors including Sequoia, CapitalG, and First Round — and crossed $100M in revenue.

In 2026, we announced our second employee tender offer https://www.nytimes.com/2026/01/28/business/dealbook/clay-start-up-tender-offers.html in 9 months at a new $5B valuation. We also launched a community equity round https://www.clay.com/blog/community-equity-offering, for our customers, agency partners, and club members.

Some things to know about us:

 - Our community http://community.clay.com includes 11,000+ customers, 150+ integration partners, 125+ agencies, 50+ Clay clubs https://luma.com/claylive, and 30k members on Slack.

 - Our culture https://nextplayso.substack.com/p/spotlight-clay is unique inside and outside of work. Our team members are also DJs, activists, writers, clowns, marathoners, skydivers, psychedelic therapists, social workers, and more.

 - All employees can work for free with world-class coaches who specialize in creativity, management, and more.

 - Our operating principles — including negative maintenance and non-attached action — guide our work. Read more about them here https://cdn.prod.website-files.com/61477f2c24a826836f969afe/685d83a71452245cc1129791_4d770abfd83e276ec15315a2e06945bd_Clay2025_OperatingPrinciples.pdf.

 - Read about us in the NYT https://www.nytimes.com/2025/08/05/business/dealbook/clay-ai-marketing-fundraise.html, Forbes http://google.com/search?q=forbes+clay&rlz=1C5OZZY_enUS1155US1155&oq=forbes+clay&gs_lcrp=EgZjaHJvbWUyBggAEEUYOTIHCAEQABiABDIHCAIQABiABDIHCAMQABiABDIHCAQQABiABDIHCAUQABiABDIHCAYQABiABDIHCAcQABiABDIHCAgQABiABDIHCAkQABiABNIBBzkzM2owajSoAgOwAgHxBVAe8UAxJx_p&sourceid=chrome&ie=UTF-8, First Round Review https://review.firstround.com/podcast/inside-clays-unconventional-path-to-1-25b/, and more https://www.clay.com/press.
   
   

Hear from our employees directly on our Glassdoor https://www.glassdoor.com/Overview/Working-at-Clay-EI_IE9850794.11,15.htm page!




SOLUTIONS ENGINEERING @ CLAY

As Head of Solutions Engineering, you will be responsible for hiring, mentoring, and developing a high-performing team of Solutions Engineers. This role is ideal for someone who wants to drive impact on the revenue side while staying closely connected to product and owning internal technical knowledge. You’re as excited about working on the technical piece of a deal as you are giving product feedback and partnering with EPD to stay up to date on new features or evolving use cases. We are seeking someone who is excited to scale our Solutions team and systems in this next phase of growth.



The Solutions Engineering team is the technical backbone of enterprise deals, helping customers push the limits of what’s possible with Clay. The team plays a critical role in the product feedback and development cycle, leveraging insights from POC builds and customer needs to inform and influence feature development. Sitting within the GTM org, Solutions Engineers partner closely with GTM Engineers (GTMEs) https://www.clay.com/blog/gtm-engineering to field technical questions, troubleshoot complex challenges, and build creative, high-impact solutions that drive revenue. The team owns and maintains Clay’s internal technical knowledge system including demo libraries, best practice playbooks, table-building guides, and the AI prompt library. They’ve built and now manage a collection of 50+ golden demos, 500+ custom AI prompts, and 20+ best practice playbooks.




IMPACT YOU’LL HAVE

 - Manage and scale the Solutions Engineering team through hiring, mentoring, and process development

 - Drive revenue growth by improving win rates and expansion through exceptional demos and POCs

 - Build world-class demo infrastructure including assets, tooling, and value narratives that demonstrate impact at scale

 - Influence product strategy by partnering cross-functionally with Sales, Product, Engineering, Marketing, and Enablement to integrate solutions expertise into go-to-market plans

 - Create a knowledge-capture system that scales team expertise: document solutions and patterns once, then transform them into internal resources (accessible via our internal AI tools) and external customer education




WHAT YOU’LL BRING

 - 6+ years as a solutions/sales Engineer OR 6+ years in a translatable role (analytics manager, technical bizops)

 - 2+ years managing technical teams

 - GTM fluency: You’ve lived in B2B SaaS and can speak the language of sales & marketing

 - Strong technical foundation in SaaS integrations and platform architecture (read - you can quickly become a Clay expert)

 - Proven ability to build scalable teams with systems, processes, and playbooks that drive efficiency

 - Excellent cross-functional collaboration with demonstrated partnerships across Sales, Product, and Marketing

 - Outstanding communication skills with experience coaching and scaling technical teams

 - Track record of leading projects and thriving in fast-paced, evolving environments

 - High bar for quality of work & attention to detail

 - Bonus: SQL experience (not required for the role)', ' - Track record of leading projects and thriving in fast-paced, evolving environments

 - High bar for quality of work & attention to detail

 - Bonus: SQL experience (not required for the role)', 'full_time', 'hybrid', 'New York', 'United States', 220000, 275000, 'USD', 'https://jobs.ashbyhq.com/claylabs/6dc3e0b7-4846-41cf-9369-6c058b3fcbc2/application', 'active', NOW(), NOW());

