VALUES ('8620de0d-538c-49a0-b13f-5d88a1d390c8', '0455617e-1070-4a2e-a38d-a5ca020222e9', 'Marketing Recruiter', 'MARKETING RECRUITER @ CLAY

We are looking for a Recruiter to handle full-cycle talent acquisition with a focus on Marketing roles. You’ll be hands on with sourcing, interview design, and closing. You’ll partner closely with hiring managers on both the “who” and the “why” of building out their teams.

Recruiting is one of the most important functions at Clay. As a company, we’re redefining how companies turn their GTM ideas into reality. And as a recruiting team, we’re redefining how we recruit and build GTM teams across Clay.




WHAT YOU’LL DO

 - Lead high-volume, full-cycle recruiting for Marketing roles at all levels - think roles like PMM, Narrative, Brand, but done the Clay way.

 - Work with teammates to ensure a delightful candidate experience, from the first conversation through each of your candidates’ first day.

 - Sourcing - lots of it! Clay has a strong pitch when it comes to revenue and growth, but we’re still in the early stages of getting the word out. And you’ll figure out new ways to source by using Clay, sourcing tools, and referral campaigns.

 - Collaborating with leadership on strategic aspects of recruiting. Success in this role isn’t just about filling requisitions, but also about quality of hire and designing effective interview processes.




