-- People Operations - Benefits & Systems
INSERT INTO jobs (id, startup_id, title, description, requirements, job_type, location_type, city, country, salary_min, salary_max, currency, application_url, status, created_at, updated_at)
VALUES ('796ad983-8c5e-4fb1-a266-ea54c5716686', '0455617e-1070-4a2e-a38d-a5ca020222e9', 'People Operations - Benefits & Systems', 'PEOPLE OPERATIONS - BENEFITS & SYSTEMS

At Clay, People Operations is about creating the environment where people can do the best work of their careers. As we continue to grow, we are looking for someone who can own our benefits, programs and systems that take care of our people and keep the experience running smoothly behind the scenes.



In this role, you''ll own benefits administration and HR systems for Clay. You''ll manage our benefits programs end to end, make sure our HRIS and related systems are accurate and well-maintained, and be the person our employees and our team can count on when something needs to work right. You''ll partner closely with Payroll, Finance, and IT to keep our data clean, our processes efficient, and our employees taken care of.



This is a hands-on role where you''ll balance day-to-day administration with process improvement. You will know when to fix something now and when to build something that scales. Above all, you''ll bring genuine care for the people you support and take full ownership of the work.




WHAT YOU''LL DO

Benefits Administration

 - Manage day-to-day administration of our global benefits programs, including health, dental, vision & retirement.

 - Build out benefit programs in new markets giving our team a comparable Clay experience, no matter where they are located

 - Serve as a main point of contact for employee benefits questions, and make sure people get clear, timely answers

 - Evaluate our benefit plans to regularly to ensure we are offering the best benefits for our team to both take care of our people and keep us competitive

 - Lead open enrollment from start to finish: communication, system setup, and vendor coordination

 - Partner with brokers and vendors on renewals, issue resolution, and evaluating our benefits offerings

 - Keep us compliant with relevant regulations (ACA, ERISA, COBRA, FMLA, and similar)

 - Audit benefits data regularly to catch and fix discrepancies before they become bigger problems



HR Systems

 - Serve as the primary administrator for our HRIS, Rippling, including employee records, workflows, and permissions

 - Build and maintain reports and dashboards in Rippling to support People team and business needs

 - Configure and maintain integrations between Rippling and our benefits

 - Set up and manage automated workflows for onboarding, offboarding, and status changes (ex. new hires, terminations, promotions, leaves)

 - Own vendor relationships for our People systems, including renewals, contract review, and evaluating new tools or add-ons

 - Troubleshoot issues and serve as the main point of contact for Rippling support

 - Create documentation and process guides so the team knows how to use these tools correctly

 - Look for ways to automate manual processes and improve how we communicate updates to employees



Build Scalable Processes and Infrastructure

 - Build out documentation, workflows, and audit processes for benefits and systems as we continue to grow

 - Keep our data organized and accurate to support reporting, compliance, and decision-making

 - Get ahead of issues before they become employee-facing problems



Partner Across the Business

 - Advise People team, managers, and employees on benefits and systems questions with clear, practical guidance

 - Make complex benefits and systems topics easy to understand for people at every level

 - Contribute to broader People Operations work as the team and company grow




WHAT YOU''LL BRING

Experience & Expertise

 - 5+ years in benefits administration, HR systems, or a combination of both

 - Hands-on experience with an HRIS

 - Solid understanding of benefits compliance requirements

 - Experience building or improving processes at a scaling company



Core Competencies

 - Autonomy and ownership: you take full accountability for your work, follow through on commitments, and don''t let things fall through the cracks

 - Genuine care: you care about the people you support, and it shows in how you handle their questions and issues

 - Exceptional attention to detail: in benefits and systems, small mistakes have big consequences; you catch them before they happen

 - Outstanding communication skills: you can translate complex benefits and systems topics into plain language

 - Highly organized with the ability to manage multiple priorities

 - Comfort with ambiguity and building structure where none exists

 - Bias toward action, balanced with sound judgment on compliance risk', 'WHAT YOU''LL BRING

Experience & Expertise

 - 5+ years in benefits administration, HR systems, or a combination of both

 - Hands-on experience with an HRIS

 - Solid understanding of benefits compliance requirements

 - Experience building or improving processes at a scaling company



Core Competencies

 - Autonomy and ownership: you take full accountability for your work, follow through on commitments, and don''t let things fall through the cracks

 - Genuine care: you care about the people you support, and it shows in how you handle their questions and issues

 - Exceptional attention to detail: in benefits and systems, small mistakes have big consequences; you catch them before they happen

 - Outstanding communication skills: you can translate complex benefits and systems topics into plain language

 - Highly organized with the ability to manage multiple priorities

 - Comfort with ambiguity and building structure where none exists

 - Bias toward action, balanced with sound judgment on compliance risk', 'full_time', 'hybrid', 'New York', 'United States', 140000, 180000, 'USD', 'https://jobs.ashbyhq.com/claylabs/fb87c93a-d5ba-4b4d-a345-3aff8fd6165d/application', 'active', NOW(), NOW());

-- People Operations - Global Mobility, Immigration, and Scale
INSERT INTO jobs (id, startup_id, title, description, requirements, job_type, location_type, city, country, salary_min, salary_max, currency, application_url, status, created_at, updated_at)
VALUES ('2254346a-b1da-4c53-bda8-a4821d7f4828', '0455617e-1070-4a2e-a38d-a5ca020222e9', 'People Operations - Global Mobility, Immigration, and Scale', 'PEOPLE OPERATIONS - GLOBAL MOBILITY, IMMIGRATION, AND SCALE

At Clay, People Operations is about creating the environment where people can do the best work of their careers. We''re growing fast and expanding globally — and global mobility is at the center of how we make that work.



In this role, you''ll own Clay''s immigration and mobility function from the ground up. You''ll manage the full lifecycle of U.S. visa cases, support employees relocating to and from our current offices in New York, San Francisco and London, and help build the infrastructure we need as we continue expanding globally. You''ll partner closely with Legal, Finance, and the People team to navigate an evolving regulatory landscape while keeping the experience human and clear for the people going through it.



This is a hands-on role where you will balance operational rigor with good judgment and knowing when to add structure and when to stay flexible. Above all, you''ll bring genuine care for the people you support and take full ownership of the work.




WHAT YOU''LL DO

Own Immigration and Global Mobility

 - Manage U.S. visa cases across the full lifecycle — from offer stage through renewals and permanent residency

 - Manage immigration and work authorization requirements for Clay''s London office, including UK visa sponsorship and right-to-work compliance

 - Serve as Clay''s internal immigration expert, partnering with external counsel to keep cases moving and employees informed

 - Advise recruiters on visa eligibility and sponsorship options as part of the hiring process

 - Partner with Legal, Finance, and People to support global expansion into new markets, building the mobility infrastructure we need as we grow



Build a Relocation Experience That Works

 - Design and manage a relocation process that feels seamless and well-supported for employees and their families

 - Manage end-to-end relocation cases, including domestic and international moves



Build Scalable Processes and Infrastructure

 - Build the mobility function from the ground up — policies, workflows, documentation, and case tracking

 - Own compliance for cross-border remote work, business travel, and international employment classification

 - Keep mobility data organized and accurate to support reporting and decision-making



Manage Contractor Operations

 - Own the end-to-end contractor lifecycle — onboarding, offboarding, and everything in between — ensuring a smooth and consistent experience

 - Maintain compliance with contractor classification requirements across U.S. and international jurisdictions

 - Partner with Legal and Finance to ensure contractor agreements are accurate, current, and audit-ready

 - Build scalable processes and documentation for contractor management, including systems tracking and recordkeeping
   
   

Partner Across the Business

 - Advise People Partners, recruiters, and business leaders on mobility-related questions with clear, practical guidance

 - Make complex immigration and mobility requirements accessible for employees navigating high-stakes processes

 - Contribute to broader People Ops work as the team and company grow




WHAT YOU''LL BRING

Experience & Expertise

 - 5+ years in People Operations with significant hands-on mobility experience

 - Experience with UK and/or European immigration and employment compliance (UK Skilled Worker visa experience a plus)

 - Experience advising on international hiring arrangements and cross-border compliance

 - Experience managing contractor populations, including onboarding/offboarding and classification compliance across jurisdictions

 - Strong vendor management skills — you know how to get the most out of immigration counsel and relocation partners

 - Experience building processes from scratch at a scaling company
   
   

Core Competencies

 - Autonomy and ownership: you take full accountability for your cases and your function, follow through on commitments, and don''t let things fall through the cracks

 - Genuine kindness and compassion: you care deeply about the people you support and it shows in every interaction, especially when employees are navigating high-stakes, high-stress situations

 - Exceptional attention to detail: in immigration, small mistakes have big consequences; you catch them before they happen

 - Outstanding communication skills: you can translate complex immigration situations into plain language for employees, leaders, and their families

 - Highly organized with the ability to manage multiple tasks

 - Comfort with ambiguity and building structure where none exists

 - Bias toward action, balanced with sound judgment on compliance risk', 'requirements for Clay''s London office, including UK visa sponsorship and right-to-work compliance

