 - Hands-on experience implementing a procure-to-pay or intake platform (Zip, Coupa, or similar)

 - Operates independently in ambiguous environments, and you don''t need a playbook to get started

 - Can push back on vendors while keeping the relationship intact', 'full_time', 'onsite', 'New York', 'United States', 170000, 215000, 'USD', 'https://jobs.ashbyhq.com/claylabs/4be52dd6-244b-4e27-bf4a-757a1094a82a/application', 'active', NOW(), NOW());

