OUT OF SCOPE

This is not an IT helpdesk or general operations role. We partner with other teams and vendors for routine operational work so you can stay focused on building scalable security foundations.', 'full_time', 'hybrid', 'New York; San Francisco', 'United States', 175000, 300000, 'USD', 'https://jobs.ashbyhq.com/claylabs/235c38ee-4c08-462d-b9b3-eadc156b1810/application', 'active', NOW(), NOW());

