INSERT INTO jobs (id, startup_id, title, description, requirements, job_type, location_type, city, country, salary_min, salary_max, currency, application_url, status, created_at, updated_at)
VALUES ('7bd1b481-bf26-4b74-8b0b-924a7d3d8a68', '0455617e-1070-4a2e-a38d-a5ca020222e9', 'Software Engineer, Full Stack', 'SOFTWARE ENGINEER, FULL STACK @ CLAY

We''re looking for a Full Stack Engineer who is responsible for building out products that help our self-serve and enterprise customers translate their growth ideas into reality. As a software engineer on these product teams, you will play a key role in achieving Clay’s vision of being a creative tool to help businesses grow by building and improving all parts of the product. You’ll wear both PM and engineering hats, working with internal as well as external stakeholders to drive features end to end — from ideation to deployment. There’ll be no shortage of fun problems to explore and technical challenges to solve.




WHAT YOU’LL DO

 - Drive product strategy and execution. You’ll work with a team of engineers and cross-functional partners across design, data science, and GTM to define a product strategy and drive execution through conception, research, implementation, and maintenance.

 - Design and build full stack features. You’ll work on a fast pace team designing and building complex features that span across both backend and frontend.

 - Up-level the codebase. Negative maintenance is one of the core values at Clay. You’ll contribute to the performance/reliability of the Clay product and help increase development velocity of other engineers.

 - Mentor and learn from other engineers. You’ll help the team grow by mentoring other engineers in areas that you’re strong in. In return, you’ll also learn from other engineers with different strengths.




WHAT YOU''LL BRING

 - You have a proven track record of execution. You have 4+ years of hands on engineering experience building world-class products.

 - You love being a product manager as well as an engineer. Our product engineers drive and own products from end to end.

 - You are an empathetic communicator. You express nuanced ideas clearly at different levels of abstraction for different audiences. In disagreements, you prioritize curiosity over confrontation, making sure everyone feels heard and understood.

 - You love to collaborate with others to ship high quality, thoughtful features. You are able to talk to customers, think through multiple approaches, and work with our teammates to find the right solution for each problem. You care about craft and translate the solution into bug free, easily understandable code and raise the engineering bar for those around you.

 - Having a diversity of perspectives is important to you. You believe that having people with different backgrounds and perspectives creates a better team and a more holistic product.

 - You’re familiar with our current tech stack or can learn unfamiliar technologies quickly. Our current tech stack is:
   
   - React, Typescript, Python, Node.js
   
   - AWS services: Aurora (Postgres), Elasticache (Redis), Elastic Container Registry (ECR), ECS (Fargate), Lambda, OpenSearch
   
   - IaC: Terraform
   
   - Deployment tools: CircleCI, Netlify, Playwright
   
   - Observability tools: Cloudwatch, Datadog, Mezmo', 'WHAT YOU''LL BRING

