VALUES ('ab415908-becf-4263-aebd-d7fb746508de', '0455617e-1070-4a2e-a38d-a5ca020222e9', 'Solutions Engineer', 'ABOUT CLAY

Our mission is to help organizations turn any growth idea into reality.

We see growth as a creative practice, not a formula. Finding and reaching your best-fit customers takes unique ideas and constant iteration. As AI makes execution faster and tactics easier to copy, creativity is the only lasting advantage. We''re already helping thousands of customers https://clayrun.notion.site/Wall-of-Love-b243f2b67607438b9fad99341e6b8d47 — including Anthropic, Notion, Google, and Ramp — go to market with unique data, signals, and AI research.

In 2025, we raised a $100M Series C https://www.nytimes.com/2025/08/05/business/dealbook/clay-ai-marketing-fundraise.htmlbacked by world-class investors including Sequoia, CapitalG, and First Round — and crossed $100M in revenue.

In 2026, we announced our second employee tender offer https://www.nytimes.com/2026/01/28/business/dealbook/clay-start-up-tender-offers.html in 9 months at a new $5B valuation. We also launched a community equity round https://www.clay.com/blog/community-equity-offering, for our customers, agency partners, and club members.

Some things to know about us:

 - Our community http://community.clay.com includes 11,000+ customers, 150+ integration partners, 125+ agencies, 50+ Clay clubs https://luma.com/claylive, and 30k members on Slack.

 - Our culture https://nextplayso.substack.com/p/spotlight-clay is unique inside and outside of work. Our team members are also DJs, activists, writers, clowns, marathoners, skydivers, psychedelic therapists, social workers, and more.

 - All employees can work for free with world-class coaches who specialize in creativity, management, and more.

 - Our operating principles — including negative maintenance and non-attached action — guide our work. Read more about them here https://cdn.prod.website-files.com/61477f2c24a826836f969afe/685d83a71452245cc1129791_4d770abfd83e276ec15315a2e06945bd_Clay2025_OperatingPrinciples.pdf.

 - Read about us in the NYT https://www.nytimes.com/2025/08/05/business/dealbook/clay-ai-marketing-fundraise.html, Forbes http://google.com/search?q=forbes+clay&rlz=1C5OZZY_enUS1155US1155&oq=forbes+clay&gs_lcrp=EgZjaHJvbWUyBggAEEUYOTIHCAEQABiABDIHCAIQABiABDIHCAMQABiABDIHCAQQABiABDIHCAUQABiABDIHCAYQABiABDIHCAcQABiABDIHCAgQABiABDIHCAkQABiABNIBBzkzM2owajSoAgOwAgHxBVAe8UAxJx_p&sourceid=chrome&ie=UTF-8, First Round Review https://review.firstround.com/podcast/inside-clays-unconventional-path-to-1-25b/, and more https://www.clay.com/press.
   
   

Hear from our employees directly on our Glassdoor https://www.glassdoor.com/Overview/Working-at-Clay-EI_IE9850794.11,15.htm page!




GTM SOLUTIONS ENGINEERING @ CLAY

The GTM Solutions Engineering team is the technical backbone of enterprise deals, helping customers push the limits of what’s possible with Clay. Whether it’s getting more out of data providers, integrating seamlessly with CRMs, or unlocking new use cases with Claygent, the team makes sure every POC is high-quality, accurate, and built to win. Sitting within the GTM org, Solutions Engineers partner closely with GTM Engineers (GTMEs) to field technical questions, troubleshoot complex challenges, and build creative, high-impact solutions that drive revenue. With Clay shipping new features daily, the team stays ahead — testing, experimenting, and implementing.




IMPACT YOU’LL HAVE

 - Own POCs from start to finish – Deliver high-quality, accurate POCs on time that directly impact enterprise sales cycles.

 - Systems thinker – You''ll set up the team to complete POCs 50% faster by templatizing, automating, and scaling best practices.

 - Drive best-in-class solutions – Answer technical questions, build out templates, and push creative solutions.

 - Partner closely with GTM-Engineers - Act as the technical counterpart to sales, ensuring they have the right solutions, data, and infrastructure to close deals.

 - Empower enterprise customers – Help them unlock the full power of Clay by leveraging data providers, CRM integrations, APIs, and Claygent to solve their biggest challenges.

 - Be the voice of the customer – Gather and report feedback to engineering, not just on bugs and feature requests, but on big-picture opportunities to make Clay even better.




WHAT YOU’LL BRING

 - 4+ years of experience in Solutions Engineering, Revops, or a technical CX role

 - A track record of systematizing Solutions Engineering work by templatizing, automating, and scaling best practices.

 - Clay experience – You already know Clay well and are comfortable working with Waterfalls, APIs, CRM integrations, Claygent, etc.

 - Excitement about partnering with sales – You thrive on working closely with GTMEs to win enterprise deals

 - Deep understanding of Revops – You know how Clay is used in enterprise sales workflows and can design solutions for real-world use cases

 - Customer-facing experience – You can confidently talk to enterprise customers, translate technical details into business impact, and present solutions clearly



This role is perfect for someone who loves solving complex problems, thrives on close collaboration with sales teams, and gets excited about using Clay to build creative, high-impact solutions. To succeed, you’ll need an impeccable eye for detail, the ability to move fast while prioritizing multiple tickets at once, and a deep understanding of how our customers use Clay.', ' - Customer-facing experience – You can confidently talk to enterprise customers, translate technical details into business impact, and present solutions clearly



This role is perfect for someone who loves solving complex problems, thrives on close collaboration with sales teams, and gets excited about using Clay to build creative, high-impact solutions. To succeed, you’ll need an impeccable eye for detail, the ability to move fast while prioritizing multiple tickets at once, and a deep understanding of how our customers use Clay.', 'full_time', 'hybrid', 'New York; San Francisco', 'United States', 160000, 210000, 'USD', 'https://jobs.ashbyhq.com/claylabs/232ab8c1-36d7-4114-91c1-0f9c9e4064bc/application', 'active', NOW(), NOW());

