VALUES ('e3c6c5c7-525a-4503-9670-4787bf70a6db', '0455617e-1070-4a2e-a38d-a5ca020222e9', 'Strategic Finance ', 'STRATEGIC FINANCE @ CLAY

We’re looking for a strategic finance rockstar who will be a key player in driving our financial strategy and fueling our growth journey. In this role, you’ll partner with our leadership team and collaborate across departments to shape financial planning, analysis, and reporting. Your insights will directly influence our decision-making and help us scale like never before. If you''re ready to roll up your sleeves and make a real impact in a fast-paced, dynamic environment, we want to hear from you!




WHAT YOU’LL DO

 - Lead the development and maintenance of financial models to support strategic decision-making, ensuring alignment with the company’s growth objectives.

 - Collaborate with cross-functional teams to analyze and report on key financial metrics, providing insights into performance trends and areas for improvement.

 - Drive the financial planning process, including annual budgets and forecasts, while ensuring accuracy and transparency in financial reporting.

 - Enhance existing financial processes and systems to streamline operations and improve data accuracy, fostering a culture of accountability and performance.




WHAT YOU''LL BRING

 - 5+ years of experience in strategic finance, financial planning and analysis, or a related field.

 - Proven track record in building and managing complex financial models, along with strong analytical skills to derive insights from data.

 - Excellent communication skills, capable of simplifying complex financial concepts for non-financial stakeholders and building strong relationships across the organization.

 - Ability to thrive in a fast-paced, dynamic environment, demonstrating initiative and adaptability in tackling challenges and driving results.', 'WHAT YOU''LL BRING

 - 5+ years of experience in strategic finance, financial planning and analysis, or a related field.

 - Proven track record in building and managing complex financial models, along with strong analytical skills to derive insights from data.

 - Excellent communication skills, capable of simplifying complex financial concepts for non-financial stakeholders and building strong relationships across the organization.

 - Ability to thrive in a fast-paced, dynamic environment, demonstrating initiative and adaptability in tackling challenges and driving results.', 'full_time', 'onsite', 'New York', 'United States', 130000, 160000, 'USD', 'https://jobs.ashbyhq.com/claylabs/6c65bbb9-8205-400c-b971-cd91897b6d8f/application', 'active', NOW(), NOW());

-- Strategic Finance - FP&A
INSERT INTO jobs (id, startup_id, title, description, requirements, job_type, location_type, city, country, salary_min, salary_max, currency, application_url, status, created_at, updated_at)
VALUES ('0f79a55a-9c22-468a-bf87-33e35219e431', '0455617e-1070-4a2e-a38d-a5ca020222e9', 'Strategic Finance - FP&A', 'STRATEGIC FINANCE - FP&A @ CLAY

We’re building a company that grows fast, moves fast, and makes decisions quickly, and Finance is a core part of that. The best FP&A functions at companies are inherently strategic, and lean on the “analysis” - they not only create a clear source of truth and planning cadence, but surface risk and opportunity early, and own what happens next with cross-functional partners.

We’re looking for an FP&A owner to build the financial systems, forecasting processes, and operating rhythms that help the business scale. You’ll partner closely with leaders across the company, own the financial model, and turn messy, ambiguous questions into clear decisions.

This is a highly cross-functional role for someone who loves combining analytical rigor with strong business judgment and creative thinking. We don''t envision this role as simply a gatekeeper of the budget (in fact, we don’t have budgets). As our first FP&A hire, you''ll help make decisions that shape the next phase of the business''s investments and growth.


WHAT YOU''LL DO

 - Own the company’s financial model and forecasting process across revenue, expenses, headcount, and cash flow

 - Lead monthly, quarterly, and annual planning cycles, including budgeting, reforecasting, and long-range planning

 - Partner with leaders across the company to help them make better, faster decisions through data and financial insight

 - Build clear reporting for leadership and analyze business performance against plan, identifying the biggest risks and opportunities

 - Create scenario analyses and business cases for new investments, hiring plans, and strategic initiatives

 - Improve and automate FP&A processes, systems, and reporting as the company scales


WHAT YOU''LL BRING

 - 5–10 years of experience in FP&A, strategic finance, investment banking, private equity, or a similarly analytical role

 - Strong financial modeling skills and experience owning budgeting, forecasting, and headcount planning

 - Ability to turn complex data into clear recommendations and communicate effectively with stakeholders across the company

 - Comfortable operating in ambiguity and building processes from scratch in a fast-growing environment

 - Strong AI and automation skills to improve Clay’s learning and growth cadence

 - Low ego, high ownership, and excited to work cross-functionally', 'WHAT YOU''LL BRING

 - 5–10 years of experience in FP&A, strategic finance, investment banking, private equity, or a similarly analytical role

 - Strong financial modeling skills and experience owning budgeting, forecasting, and headcount planning

 - Ability to turn complex data into clear recommendations and communicate effectively with stakeholders across the company

 - Comfortable operating in ambiguity and building processes from scratch in a fast-growing environment

 - Strong AI and automation skills to improve Clay’s learning and growth cadence

 - Low ego, high ownership, and excited to work cross-functionally', 'full_time', 'onsite', 'New York', 'United States', 170000, 210000, 'USD', 'https://jobs.ashbyhq.com/claylabs/11523b92-635e-4865-8ed0-59ef4c91bd53/application', 'active', NOW(), NOW());

